  ViewContainerRef,
} from '@angular/core';
import {DOCUMENT} from '@angular/common';
import {Directionality} from '@angular/cdk/bidi';
import {coerceBooleanProperty} from '@angular/cdk/coercion';
type BooleanInput = string | boolean | null | undefined;
import {DOWN_ARROW, ENTER, ESCAPE, TAB, UP_ARROW, hasModifierKey} from '@angular/cdk/keycodes';
import {focusedElementPierceShadowDom} from './owned-shadow-dom';
import {legacyGetEventTarget} from '@ngx-compat/material-legacy/legacy-core';
import {TemplatePortal} from '@angular/cdk/portal';
import {_LegacyViewport as ViewportRuler} from '@ngx-compat/material-legacy/legacy-core';
import {BreakpointObserver, Breakpoints} from '@angular/cdk/layout';
import {
  FlexibleConnectedPositionStrategy,
  Overlay,
  OverlayConfig,
  OverlayRef,
  PositionStrategy,
  ScrollStrategy,
  ConnectedPosition,
} from '@angular/cdk/overlay';
import {ControlValueAccessor} from '@angular/forms';
import {
  MatLegacyOptionSelectionChange as MatOptionSelectionChange,
  _countGroupLabelsBeforeLegacyOption as _countGroupLabelsBeforeOption,
  _getLegacyOptionScrollPosition as _getOptionScrollPosition,
  _MatLegacyOptionBase as _MatOptionBase,
} from '@ngx-compat/material-legacy/legacy-core';
import {MAT_LEGACY_FORM_FIELD as MAT_FORM_FIELD, MatLegacyFormField as MatFormField} from '@ngx-compat/material-legacy/legacy-form-field';
